package io.tuji.app;
import org.junit.Test;import static org.junit.Assert.*;import java.nio.file.*;import java.io.*;
public class TaskCacheTest {
 @Test public void activeTasksSurviveCleanupAndIdleTasksAreRemoved()throws Exception{File parent=Files.createTempDirectory("tuji-cache").toFile(),root=new File(parent,"jobs");TaskCache cache=new TaskCache(root);File dir=cache.allocate("send-");dir.mkdirs();Files.write(new File(dir,"a.part").toPath(),new byte[123]);File original=new File(parent,"original.jpg");Files.write(original.toPath(),new byte[55]);cache.active(true);assertArrayEquals(new long[]{123,123,0},cache.stats());cache.clean();assertTrue(dir.exists());cache.active(false);assertEquals(0,cache.clean());assertTrue(original.exists());assertArrayEquals(new long[]{0,0,0},cache.stats());PhotoBundle.deleteTree(parent);}
 @Test public void idleRemainsCleanableWhileCurrentTaskIsActive()throws Exception{File root=Files.createTempDirectory("tuji-active").toFile();TaskCache cache=new TaskCache(root);Files.write(new File(root,"old.part").toPath(),new byte[17]);cache.active(true);File current=cache.allocate("send-");Files.write(current.toPath(),new byte[31]);assertArrayEquals(new long[]{48,31,17},cache.stats());cache.clean();assertTrue(current.exists());assertFalse(new File(root,"old.part").exists());cache.active(false);assertEquals(0,cache.clean());PhotoBundle.deleteTree(root);}
 @Test public void restartRecoversIdleFiles()throws Exception{File root=Files.createTempDirectory("tuji-restart").toFile();Files.write(new File(root,"incoming-123").toPath(),new byte[35]);TaskCache recovered=new TaskCache(root);assertEquals(35,recovered.stats()[2]);assertEquals(0,recovered.clean());PhotoBundle.deleteTree(root);}
 @Test public void hashHonorsCancellation()throws Exception{File f=File.createTempFile("tuji-hash","tmp");Files.write(f.toPath(),new byte[600000]);try{PhotoBundle.hash(f,(d,t)->{throw new IOException("cancel");});fail();}catch(IOException expected){assertEquals("cancel",expected.getMessage());}finally{f.delete();}}
}
